style.css:
@-moz-document url-prefix("https://"), url-prefix("http://") {
body {
        background-color: #FADADD !important; /* baby pink */
        background-image: none !important;
        color: #000000 !important; /* optional: make text readable */
    }

    /* Optional - make other elements match */
    div, section, article, main {
        background-color: #FDEDF3 !important; /* slightly lighter pink for contrast */
    }
}
